// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint _val) public {
        // Assume a reasonable value for _val
        vm.assume(_val <= type(uint256).max / 2);

        // Call SetMinSum before Initialized (should succeed in reference, revert in buggy)
        c.SetMinSum(_val);

        // Now call Collect with any valid parameters; we just need to observe whether MinSum was set
        // To trigger Collect, we need to put some balance first
        vm.deal(address(this), 1 ether);
        c.Put{value: 1 ether}(0);

        // Try Collect with a small amount
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, 0));

        // The general rule: if SetMinSum did not revert, then MinSum was set to _val
        // After the sequence, c.MinSum() should equal _val
        assertTrue(c.MinSum() == _val);
    }
}

