pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _am, uint256 _val) public {
        // Deploy and initialize the contract so Collect can be called.
        // Set MinSum to 0 so Collect has a chance to run.
        c.SetMinSum(0);
        c.Initialized();
        // Send some ether to address(c) so Collect can transfer.
        vm.deal(address(c), 1 ether);
        // Call Collect with _am; it may revert, but we don't care.
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _am));
        // After Collect, call SetMinSum with _val.
        // The buggy version will always revert; the reference should not revert.
        c.SetMinSum(_val);
        // Assert that MinSum is now _val.
        assertTrue(c.MinSum() == _val);
    }
}

