// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val1, uint256 _val2, uint256 _lockTime, uint256 _am, uint256 _putValue) public {
        // Ensure _val2 is not 0 to avoid trivial case where both SetMinSum calls set to 0
        vm.assume(_val1 != _val2);
        // Ensure _putValue is not too large to avoid arithmetic overflow in Put
        vm.assume(_putValue <= type(uint256).max - _putValue);
        // Ensure _lockTime is reasonable
        vm.assume(_lockTime <= 1000000000);

        // Set up the contract: initialize and set MinSum to _val1
        c.SetMinSum(_val1);
        c.Initialized();

        // Call Put to give the caller balance
        vm.deal(address(this), _putValue);
        (bool success,) = address(c).call{value: _putValue}("");
        require(success, "Put failed");

        // Simulate time passing beyond the latest unlockTime
        vm.warp(block.timestamp + _lockTime + 1);

        // Call Collect with some amount (will revert if conditions not met, but that's fine)
        (bool collectSuccess,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _am));
        // Collect may revert; we just need to check MinSum after the call
        // Re-call SetMinSum with a new value _val2 
        vm.prank(address(0x1234)); // use a different caller to avoid potential issues
        (bool setSuccess,) = address(c).call(abi.encodeWithSelector(c.SetMinSum.selector, _val2));

        // In the reference, SetMinSum should succeed because it checks !initialized which is false after Initialized
        // In the buggy version, SetMinSum checks !initialized which is true (since initialized is true), so it reverts
        // So we check that MinSum equals _val2 if SetMinSum succeeded, otherwise it remains _val1
        uint256 minSumAfter = c.MinSum();
        assertTrue(setSuccess ? minSumAfter == _val2 : minSumAfter == _val1);
    }
}

