        // Call Collect - for reference, it should not revert when balance >= minSum and >= withdraw and time > unlock
        bool reverted = false;
        try c.Collect(_withdraw) {
            // success
        } catch {
            reverted = true;
        }

        // The property: Collect should not revert if the caller has enough balance and time is right
        // Since we satisfy those, Collect should never revert
        assertTrue(!reverted);
