        uint256 minSumBefore = c.MinSum();

        // Put some ETH into the contract
        vm.deal(address(this), _putValue);
        c.Put{value: _putValue}(_lockTime);

        // Warp time past unlock
        vm.warp(block.timestamp + _lockTime + 1);

        // Set MinSum to a value that enables collect
        c.SetMinSum(0); // note: in reference, this sets to 0; in mutant, also 0
        // Actually, to ensure MinSum changes only via SetMinSum, we set it to a non-zero value
        // But we need a general rule: MinSum should not change during Collect
        // So let's set a specific value and check it remains
        c.SetMinSum(12345);
        minSumBefore = c.MinSum();

        // Call Collect
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _collectAm));
        // We don't care if it succeeds or reverts; just record the outcome

        // The rule: MinSum after Collect equals MinSum before Collect
        uint256 minSumAfter = c.MinSum();
        assertTrue(minSumAfter == minSumBefore);
    }
}

