pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 deposit, uint256 collectAmt) public {
        // Bound inputs to avoid overflow reverts
        vm.assume(lockTime < type(uint256).max - block.timestamp);
        vm.assume(collectAmt <= deposit); // For simplicity, collect amount not exceeding deposit
        // If deposit is 0, skip because Put may revert (no msg.value)
        vm.assume(deposit > 0);

        // Set MinSum via SetMinSum (before initialized)
        c.SetMinSum(minSum);
        uint256 expectedMinSum = minSum;

        // Initialize
        c.Initialized();

        // Fund the test contract and put
        vm.deal(address(this), deposit);
        c.Put{value: deposit}(lockTime);

        // Try Collect
        bool collectSuccess;
        try c.Collect(collectAmt) {
            collectSuccess = true;
        } catch {
            collectSuccess = false;
        }

        // After Collect, MinSum should be the value set by SetMinSum (in reference it's minSum, in mutant it's 0)
        // So we assert equality
        emit log_named_uint("Expected MinSum", expectedMinSum);
        emit log_named_uint("Actual MinSum", c.MinSum());
        assertTrue(c.MinSum() == expectedMinSum);
    }
}

