pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 _lockTime, uint256 _amount, uint256 _minSum) public {
        // Assume _minSum is non-zero to make the property interesting
        vm.assume(_minSum > 0);

        // First, set MinSum (only possible before initialization)
        c.SetMinSum(_minSum);

        // Send some ETH to the contract to have balance
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "Put failed");

        // Now call Collect - it may revert or succeed
        // We wrap in try/catch to handle potential revert
        bool collectReverted;
        try c.Collect(0) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // The general rule: after Collect, MinSum should still be the value we set
        // unless the contract was initialized (which it wasn't)
        uint256 minSumAfterCollect = c.MinSum();

        // In the reference contract, SetMinSum works as intended, so MinSum should be _minSum
        // In the mutant, SetMinSum does nothing, so MinSum remains 0
        assertTrue(minSumAfterCollect == _minSum || minSumAfterCollect == 0);
    }
}

