        // Record the caller's balance before collect
        uint256 balanceBefore = c.Acc(caller).balance;

        // Attempt to collect
        vm.prank(caller);
        c.Collect(collectAmount);

        // Check the invariant: Collect should only reduce balance if collectAmount <= balance
        uint256 balanceAfter = c.Acc(caller).balance;

        // The general rule: balance should never increase, and if balance >= minSum and collectAmount <= balance, it should decrease
        assertTrue(balanceAfter <= balanceBefore);

