        if (balanceBefore >= minSum && collectAmount <= balanceBefore) {
            assertTrue(balanceAfter == balanceBefore - collectAmount);
        }

        // If balanceBefore < minSum, the collect should not change balance
        if (balanceBefore < minSum) {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
